-- Généré par tests/build_guide.lua depuis GUIDE.md : ne pas éditer à la main.
local _, NS = ...
NS.guides = NS.guides or {}
NS.guides.enUS = {
    { "h1", "Panorama guide" },
    { "p", "How to use Panorama on WoW Forever, and how to set up HDR on Windows." },
    { "p", "|cffffd100Back up your settings first.|r Panorama changes game settings, and removing the addon does not change them back. Before you change anything, quit the game and copy the |cffffd100WTF|r folder of your game install somewhere safe. To go back, quit the game and put that copy back in place." },
    { "h2", "1. Open the window" },
    { "li", "Type |cffffd100/pano|r, or left click the Panorama button on the minimap.", "-" },
    { "li", "Options > AddOns > Panorama also has a button that opens it.", "-" },
    { "li", "Drag the title bar to move the window. Escape or the close button closes it.", "-" },
    { "p", "The minimap button:" },
    { "li", "Left click opens or closes the window.", "-" },
    { "li", "Right click shows the presets, undo, redo and graphics restart.", "-" },
    { "li", "Drag it to move it around the minimap. |cffffd100/pano minimap|r shows or hides it.", "-" },
    { "h2", "2. The window" },
    { "row", "|cffffd100Simple|r, |cffffd100Advanced|r (next to the title)", "Simple: each tab shows a short list of the main settings, without sections. Advanced: every setting, by section, with the rules per place and the Experts section. On first install it is Simple; if you already used Panorama, it is Advanced. The search always finds every setting." },
    { "row", "Guide (top right)", "Opens this guide in the game." },
    { "row", "|cffffd100Options|r menu (top right)", "|cffffd100Language|r (game language or one of ten languages; changing it reloads the interface), |cffffd100Apply on every login|r, |cffffd100Minimap button|r, |cffffd100Reset all…|r." },
    { "row", "|cffffd100Current look:|r (bar under the title)", "The look on the world now, and who sets it: you, Day and night, or the place. Its button (|cffffd100Edit|r, |cffffd100Edit this rule|r) opens where to change it. Hover the bar to see which one comes first." },
    { "row", "Tabs", "|cffffd100Image|r (graphics quality), |cffffd100HDR|r, |cffffd100Ambiance|r (look of the world), |cffffd100My filters|r. The open tab is remembered." },
    { "row", "Search box (right of the tabs)", "Type a word to list the matching settings of every tab. Clear it to go back." },
    { "row", "Presets (Image tab)", "Low, Medium, High, Extra. The preset that matches your settings is highlighted." },
    { "row", "Footer", "|cffffd100Undo|r cancels your last change: slider, box, preset, filter, ambiance or Reset all. |cffffd100Redo|r puts it back. The last 20 changes are kept until |cffffd100/reload|r. |cffffd100Restart|r restarts the graphics engine." },
    { "p", "In Advanced mode, click a section title to fold or unfold it. The |cffffd100Experts (console only)|r section starts folded. A section title shows how many of its settings you changed." },
    { "h3", "A setting line" },
    { "li", "|cffffd100Slider|r: the value is written when you release the mouse button, not while you drag.", "-" },
    { "li", "|cffffd100Value box|r next to the slider: type a value, then press Enter or click elsewhere. Escape cancels, Tab goes to the next box. A comma works as decimal point. The value is kept within the slider's range.", "-" },
    { "li", "|cffffd100Default button|r: puts that setting back to its default value. Hover it to see the value.", "-" },
    { "li", "|cffffd100Gold mark|r on the left: you changed this setting.", "-" },
    { "li", "|cffffd100Game menu|r: when a game menu also sets this value, the help of the label names it. That menu does not read the value back, so it may show another level.", "-" },
    { "li", "|cffffd100Greyed line|r: it depends on another setting that is off (for example |cffffd100Volumetric fog quality|r without |cffffd100Volumetric fog|r, tint strength without a tint), or a mode sets it. Hover the label to see why. A line that depends on another one is shifted to the right, just under it.", "-" },
    { "li", "Hover a label to read its full help.", "-" },
    { "h2", "3. Presets" },
    { "row", "Low", "Best performance. Short view distance, no shadows." },
    { "row", "Medium", "Balanced. Good performance with decent shadows." },
    { "row", "High", "The game's High level. Full shadows, all effects." },
    { "row", "Extra", "High, with the longest view distance." },
    { "p", "Presets change only the graphics quality settings of the Image tab. They do not touch camera, mouse, interface, sharpening, low latency, HDR or filters." },
    { "p", "Changed your mind? |cffffd100Undo|r (footer, or |cffffd100/pano undo|r) restores the settings from before the preset." },
    { "h2", "4. Ambiance" },
    { "p", "The Ambiance tab sets the look of the world: effects on top of the image. They change no game setting." },
    { "li", "|cffffd100Mode|r (top of the tab): |cffffd100Fixed|r (the same filter everywhere), |cffffd100Day and night|r (a day tint and a night tint) or |cffffd100By place|r (see below). Fixed by default.", "-" },
    { "li", "|cffffd100Here|r: the place and the time of day detected now. When a dungeon, indoors or the weather comes before a zone you set, it says so.", "-" },
    { "li", "|cffffd100Filter|r (Fixed and Day and night modes): |cffffd100Base|r uses the lines below. One of your filters (My filters tab) replaces the tint, the vignette and the film grain, and brings its contrast, brightness and gamma. |cffffd100Edit filter|r opens it in the My filters tab.", "-" },
    { "li", "|cffffd100Color tint|r: click a thumbnail to apply it right away (sepia, warm, cold, night, emerald, dusk). |cffffd100Tint strength|r sets how strong it is.", "-" },
    { "li", "|cffffd100Vignette|r: darkens the edges of the screen.", "-" },
    { "li", "|cffffd100Film grain|r: animated grain.", "-" },
    { "li", "|cffffd100Day tint|r and |cffffd100Night tint|r (Day and night mode): Panorama lays the day tint by day and the night tint at night, following the game's day and night. They replace the color tint. The change is gradual from 19:00 to 21:00 and from 5:00 to 7:00 (server time). One of your filters chosen on the Filter line replaces them.", "-" },
    { "li", "|cffffd100Sky|r: the same colors as a gradient, full at the top of the screen and lighter at the bottom. |cffffd100Sky strength|r sets how strong it is.", "-" },
    { "li", "|cffffd100Black bars|r: top and bottom bars, 0 to 20 % of the screen each, in every mode. The game still renders what they hide, so they do not raise the frame rate.", "-" },
    { "p", "In Simple mode, the tab shows the mode, the place, the filter, the color tint and its strength, and the day and night tints. Vignette, film grain, sky and black bars are in Advanced mode." },
    { "h3", "By place" },
    { "p", "In |cffffd100By place|r mode, the tint, sky, vignette and grain change on their own, to fit where you are." },
    { "li", "The lines of the Fixed mode are hidden: the rule of the place replaces them. Only the black bars stay. Their values stay saved and come back when you change the mode. In Simple mode, the shipped rules apply; choose Advanced to edit them.", "-" },
    { "li", "|cffffd100Place|r: sets the tint, vignette and grain. Order: dungeon or raid, indoors, weather (rain, snow, sandstorm), then the kind of zone: temperate, desert, snowy, jungle and marsh, corrupted, volcanic, arcane forest. A zone not known yet counts as temperate. Weather counts only when Weather intensity is above 0.", "-" },
    { "li", "|cffffd100Time of day|r: sets the sky (day, dawn and dusk, night). Night follows the game's day and night; dawn and dusk follow the server time. No sky indoors or in a dungeon.", "-" },
    { "li", "|cffffd100Rule|r (Advanced mode): pick a rule, then set it below. The Default button gives back the value shipped for that rule. The first time the window opens in a session, the rule of the place you are in is open. The menu has five groups: |cffffd100Zones|r (the zone you are in and the zones you set), |cffffd100Dungeon and indoors|r, |cffffd100Weather|r, |cffffd100Zone type|r and |cffffd100Sky (time of day)|r. The first four set tint, vignette, grain and a graphics preset: one place applies at a time, in the order given above. The last one sets the sky. Nothing to set to get started: every rule already has its values.", "-" },
    { "li", "|cffffd100This zone|r: first choice of the same menu, with the name of the zone you are in. Pick it to give this zone its own tint, vignette and grain, starting from its kind of zone. It then comes before the kind of zone, but after dungeon, indoors and weather. Zones you set stay in the menu. |cffffd100Back to zone type|r (next to the menu) removes the values of the zone: it follows its kind of zone again.", "-" },
    { "li", "|cffffd100All zones|r: submenu of the same menu, with every known zone. Pick one to set it without being there. Zones are sorted by continent.", "-" },
    { "li", "|cffffd100Graphics preset|r and |cffffd100Scenery distance|r (section |cffffd100Image|r of a place or a zone): they apply while you are in that place, over your own settings, whatever the ambiance mode. The scenery distance of the place comes before the one of the preset. Your own settings are kept and come back when you leave. |cffffd100My settings|r changes nothing. Example: Low in dungeons, Extra in a zone you like. In a dungeon or raid, the first choice of the menu sets that dungeon alone. In the Image tab, |cffffd100Here: …|r shows next to the presets while a place applies its own; in Advanced mode, it opens that rule. In combat, the change waits for the end of the fight.", "-" },
    { "li", "|cffffd100Filter|r (first line of section |cffffd100Look|r of a place or a zone): this place uses one of your filters from the My filters tab, with its contrast, brightness and gamma. |cffffd100Settings below|r: the tint, vignette and grain of the rule. The Look section applies only in By place mode.", "-" },
    { "h2", "5. My filters" },
    { "p", "The My filters tab lets you create as many filters of your own as you want. The open filter shows on the world only as a preview; the filter that applies is chosen in the Ambiance tab. |cffffd100New|r adds one and opens it, |cffffd100Delete|r removes the open one: the Ambiance tab filter and the rules that used it go back to no filter. One filter always remains." },
    { "li", "|cffffd100Filter|r: picks the filter that the lines below set. |cffffd100Name|r: give it a name (Enter to confirm).", "-" },
    { "li", "|cffffd100Color tint|r: click a thumbnail to give the filter that color. |cffffd100Red|r, |cffffd100Green|r, |cffffd100Blue|r (in %): its exact color. |cffffd100Tint strength|r: how strong it is.", "-" },
    { "li", "|cffffd100Vignette|r and |cffffd100Film grain|r: those of the filter.", "-" },
    { "li", "|cffffd100Contrast|r, |cffffd100Brightness|r, |cffffd100Gamma|r: image settings the filter gives the game while it is applied; your own values come back afterwards. My settings: nothing changes. Depending on the display mode, they may have no effect.", "-" },
    { "li", "In Simple mode, the tab shows only the color tint and the tint strength.", "-" },
    { "li", "While the tab is open, the filter shown is visible live on the game. The |cffffd100Current look:|r bar says when it is only a preview.", "-" },
    { "li", "To use a filter: pick it on the |cffffd100Filter|r line of the Ambiance tab (Fixed and Day and night modes), or of a place or a zone (By place mode). It then replaces the tint, the vignette and the film grain. |cffffd100Base|r or |cffffd100Settings below|r: nothing changes.", "-" },
    { "h2", "6. Your values and the game" },
    { "li", "On first install, Panorama reads your current game settings. Nothing changes until you move a control.", "-" },
    { "li", "A change made in the game's Graphics menu or with |cffffd100/console|r shows in the window.", "-" },
    { "li", "|cffffd100Apply on every login|r (Options menu, on by default): the settings you changed in Panorama are written again at each login. The others follow the game's Graphics menu.", "-" },
    { "li", "A change made during combat is applied when combat ends.", "-" },
    { "li", "Some settings, such as MSAA, need a graphics restart. Click |cffffd100Restart|r in the footer, or type |cffffd100/pano restart|r. The screen flickers for a second.", "-" },
    { "h2", "7. HDR on Windows" },
    { "p", "HDR settings exist only as console commands in the game. Panorama shows them in the |cffffd100HDR|r tab. You need a monitor that supports HDR." },
    { "h3", "Step 1: turn on HDR in Windows" },
    { "p", "Windows 11:" },
    { "li", "Open |cffffd100Settings > System > Display|r.", "1." },
    { "li", "Select the HDR monitor if you have more than one.", "2." },
    { "li", "Turn on |cffffd100Use HDR|r. The shortcut |cffffd100Win + Alt + B|r also turns it on or off.", "3." },
    { "p", "Windows 10: |cffffd100Settings > System > Display > Windows HD Color settings|r, then turn on |cffffd100Play HDR games and apps|r." },
    { "p", "Also check that HDR is on in the monitor's own menu, if it has such an option." },
    { "p", "Turn off |cffffd100Auto HDR|r in Windows 11: |cffffd100Settings > System > Display > HDR|r. Auto HDR is meant for games without HDR. WoW makes its own HDR image." },
    { "h3", "Step 2: find the peak brightness of your monitor" },
    { "p", "Install the free |cffffd100Windows HDR Calibration|r app from the Microsoft Store and run it. The maximum luminance it finds is the peak brightness of your monitor, in nits." },
    { "p", "Without the app, use the monitor's HDR rating: DisplayHDR 400 means about 400 nits, DisplayHDR 600 about 600, DisplayHDR 1000 about 1000." },
    { "h3", "Step 3: set HDR in Panorama" },
    { "p", "Open |cffffd100/pano|r, tab |cffffd100HDR|r. In Simple mode, the tab shows only the first three lines below: choose |cffffd100Advanced|r to see |cffffd100HDR intensity|r and the reference brightness." },
    { "li", "Check |cffffd100HDR output|r.", "1." },
    { "li", "Check |cffffd100Use peak brightness|r or |cffffd100Use reference brightness|r: one of the two, never both. Without one, the image goes dark.", "2." },
    { "p", "|cffffd100Peak brightness mode (recommended)|r" },
    { "li", "Check |cffffd100Use peak brightness|r.", "-" },
    { "li", "Set |cffffd100Peak brightness (nits)|r to the value found in step 2.", "-" },
    { "li", "|cffffd100HDR intensity|r works only in this mode. The game's default is 2. Change it in small steps and compare: Blizzard does not document its exact effect.", "-" },
    { "p", "|cffffd100Reference brightness mode|r" },
    { "li", "Check |cffffd100Use reference brightness|r.", "-" },
    { "li", "|cffffd100Reference brightness (nits)|r is the brightness of white in the scene. 203 is the standard value. Raise it if the image looks too dark in a bright room. HDR intensity has no effect in this mode.", "-" },
    { "p", "If the image does not change, click |cffffd100Restart|r in the footer." },
    { "h3", "HDR troubleshooting" },
    { "row", "Image very dark", "Check one of the two brightness modes." },
    { "row", "Image grey or washed out", "Turn on HDR in Windows (step 1) and in the monitor's menu." },
    { "row", "Auto HDR on in Windows", "Turn it off (step 1)." },
    { "row", "Highlights too bright or flat", "Set the peak brightness to the real value of your monitor (step 2)." },
    { "row", "You want HDR off", "Uncheck |cffffd100HDR output|r." },
    { "p", "Each HDR line has a Default button that puts back the game's value." },
    { "h2", "8. Commands" },
    { "row", "|cffffd100/pano|r", "Open or close the window" },
    { "row", "|cffffd100/pano low|r, |cffffd100/pano medium|r, |cffffd100/pano high|r, |cffffd100/pano extra|r", "Apply a preset" },
    { "row", "|cffffd100/pano undo|r", "Cancel the last change" },
    { "row", "|cffffd100/pano redo|r", "Put back the change you just undid" },
    { "row", "|cffffd100/pano reset|r", "Put every setting and filter back to its default" },
    { "row", "|cffffd100/pano status|r", "Show in the chat the place and time of day detected and the filters applied now (during a fade, the values it goes to)" },
    { "row", "|cffffd100/pano apply|r", "Write again the settings changed in Panorama" },
    { "row", "|cffffd100/pano restart|r", "Restart the graphics engine" },
    { "row", "|cffffd100/pano minimap|r", "Show or hide the minimap button" },
    { "row", "|cffffd100/pano blackbars 10|r", "Black bars at 10% of the screen height (0 to 20). |cffffd100off|r removes them" },
    { "row", "|cffffd100/pano grain 10|r", "Film grain at 10 (0 to 100). |cffffd100off|r removes it" },
    { "row", "|cffffd100/pano vignette 10|r", "Vignette at 10 (0 to 100). |cffffd100off|r removes it" },
    { "h2", "9. Reset" },
    { "li", "The |cffffd100Default|r button on each line resets that setting.", "-" },
    { "li", "The |cffffd100Defaults|r button of the game's Graphics menu resets only the settings that menu manages, and Panorama follows it. Use the Default buttons in |cffffd100/pano|r for the others and for the filters.", "-" },
    { "li", "|cffffd100Reset all…|r (Options menu, with confirmation) or |cffffd100/pano reset|r: puts every setting in the window, changed in Panorama or not, and every filter back to its default. |cffffd100Undo|r cancels it until |cffffd100/reload|r. The Ambiance tab and the zones you set are reset too. Your filters in the My filters tab are erased too.", "-" },
}
